;width:76px;height:76px;border-radius:50%;border:3px solid #fff9;background:#103b68aa;color:white;font-size:28px;font-weight:900;display:flex;align-items:center;justify-content:center;opacity:.78;user-select:none}.servezone{position:absolute;width:70px;height:70px;border:2px solid #fff7;border-radius:50%;right:24px;bottom:110px;pointer-events:auto;color:white;text-align:center;font-size:11px;font-weight:900;padding-top:20px;background:#ef4d75aa}.winlabel{font-size:26px;margin:10px 0 18px;font-weight:900}.shake{animation:shake .25s}@keyframes shake{50%{transform:translateX(8px)}}
