let started=false,rally=true,paused=false,points=[0,0],match=[0,0],lastTouch=0;
const p={x:.5,y:.78,vx:0,side:1,swing:0};const cpu={x:.5,y:.25,vx:0,side:-1,swing:0};let ball={x:.5,y:.52,z:.12,vx:.16,vz:.15,vy:.38,owner:'cpu',hit:false};
function resetBall(server=1){ball={x:.5+(server?-0.02:0.02),y:server?.30:.72,z:.12,vx:0,vz:server?-.25:.25,vy:.65,owner:'cpu',hit:false};rally=true}
function point(who){points[who]++;match[who]=points[who]>=4?1:0;if(points[who]>=4&&points[who]-points[1-who]>=2){match[who]++;points=[0,0]}if(match[who]>=2){end(who)}else{setTimeout(()=>resetBall(who),700)}}
function end(who){started=false;paused=true;const o=document.getElementById('overlay'),w=document.getElementById('win');w.textContent=(who===0?'VICTORY! YOU WIN':'MATCH LOST — CPU WINS');w.classList.remove('hidden');document.getElementById('sub').textContent='TENNIS MASTERS';document.getElementById('start').textContent='PLAY AGAIN';o.classList.remove('hidden')}
function start(){document.getElementById('overlay').classList.add('hidden');document.getElementById('win').classList.add('hidden');points=[0,0];match=[0,0];started=true;paused=false;p.x=.5;cpu.x=.5;resetBall(1)}document.getElementById('start').onclick=start;
