function player(a,isCPU){const sc=ctx;let px=a.x*W;let py=isCPU?H*(.25+(a.y-.25)*.55):H*(.66+(a.y-.66)*.35);if(!isCPU)py=a.y*H;else py=a.y*H*.75+.02*H;const s=Math.max(.55,Math.min(1.15,W/900));sc.save();sc.translate(px,py);sc.scale(s,s);sc.shadowColor='#0005';sc.shadowBlur=12;sc.fillStyle=isCPU?'#ef4d75':'#18b9df';sc.beginPath();sc.ellipse(0,10,18,38,0,0,7);sc.fill();sc.fillStyle=isCPU?'#ffcc6a':'#ffe14f';sc.beginPath();sc.arc(0,-30,15,0,7);sc.fill();sc.fillStyle=isCPU?'#a54d6d':'#3d7d9e';sc.fillRect(-11,-18,22,35);sc.fillStyle='#fff';sc.beginPath();sc.ellipse(0,42,24,8,0,0,7);sc.fill();sc.save();sc.rotate(-1.1+a.swing);sc.strokeStyle='#7d5535';sc.lineWidth=4;sc.beginPath();sc.moveTo(12,-10);sc.lineTo(35,-32);sc.stroke();sc.strokeStyle='#ddd';sc.lineWidth=3;sc.beginPath();sc.ellipse(39,-35,10,20,-.5,0,7);sc.stroke();sc.restore();sc.restore()}
