function update(){if(!started)return;if(keys.a)p.vx-=.0018;if(keys.d)p.vx+=.0018;p.vx*=.86;p.x=Math.max(.32,Math.min(.68,p.x+p.vx));if(keys.swing&&p.swing<=0){p.swing=.6;const dx=ball.x-p.x,dy=ball.y-p.y;if(Math.abs(dx)<.18&&Math.abs(dy)<.28&&ball.y>.58){ball.owner='p';ball.vx=-dx*.3+ (Math.random()-.5)*.05;ball.vz=-.55-(keys.lob?.12:0);ball.vy=keys.lob?.9:.62;ball.hit=true}}if(keys.lob&&p.swing<=0)p.swing=.35;p.swing=Math.max(0,p.swing-.04);cpu.vx=(ball.x-cpu.x)*.018;cpu.x=Math.max(.32,Math.min(.68,cpu.x+cpu.vx));if(Math.abs(ball.x-cpu.x)<.16&&ball.y<.32&&ball.vz<0&&!ball.hit){cpu.swing=.5;ball.owner='cpu';ball.vx=(p.x-ball.x)*.12+(Math.random()-.2)*.05;ball.vz=.55;ball.vy=.68}cpu.swing=Math.max(0,cpu.swing-.04);
